architecture.h4_f:
msg = CBOR{v:1, ข้อความ, Reply_to, send_at}
ct = AES-GCM-256-เข้ารหัส (k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {ข้อความเข้ารหัส: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, ข้อความ, Reply_to?, thread_id?, กล่าวถึง?, send_at}
ct = AES-GCM-256-เข้ารหัส (room_key, nonce, pt, aad=hex(room_id))
ลวด = CBOR{
  วี: 1,
  ไซเฟอร์เท็กซ์: hex(ct), // ความยาวผันแปรได้
  nonce: ฐานสิบหก (12 B)
  sender_pseudo: ฐานสิบหก (16 B)
  send_at: unix_ms
}

cryptoWire.h5_f:
ภายนอก = CBOR{
  source_node: hex32,
  target_user: int64,
  inner_ciphertext: ไบต์,
  inner_nonce: ไบต์
  send_at: unix_ms
}
sig = Ed25519-Sign (source_priv, ด้านนอก)
POST /federation/deliver { ซองจดหมาย: ด้านนอก, sig: hex64 }

auth.h1_f:
POST /api/authentication/register
  { ชื่อผู้ใช้, รหัสผ่าน, x25519_public_key, display_name, โทรศัพท์?, อีเมล?, avatar_emoji }

ตอบกลับ 201 สร้างแล้ว:
  { access_token, Refresh_token, user_id, ชื่อผู้ใช้, ... }

auth.h3_f:
เพย์โหลด access_token:
  { ย่อย: user_id, jti: device_id, พิมพ์: "เข้าถึง", ประสบการณ์: ตอนนี้ + 15 นาที }
เพย์โหลด Refresh_token:
  { ย่อย: user_id, jti: device_id, พิมพ์: "รีเฟรช", exp: ตอนนี้ + 30d }

HS256 ลงนามด้วยความลับ 64 ไบต์ของโหนดจาก .env

auth.h4_f:
register_begin(): ความท้าทาย = แรนด์ (32)
                    ตัวเลือก = { rp.id, user.id, pubKeyCredParams, ความท้าทาย }
                    ตัวเลือกการส่งคืน

register_finish(รับรอง):
  ตรวจสอบการรับรองกับ TPM / Secure Enclave root CA
  ร้านค้า { credential_id, public_key, ตัวนับ: 0 }

auth.h7_f:
POST /api/authentication/qr/begin
  → { nonce: ฐานสิบหก 128 บิต, ttl: 60 }
QR payload = { nonce, user_id, เซิร์ฟเวอร์: "https://node.example" }

POST /api/authentication/qr/verify { nonce }
  → อุปกรณ์ใหม่ที่ลงทะเบียน; JWT กลับมาแล้ว

rooms.h6_f:
sender_pseudo = HMAC-SHA256(room_pseudo_salt, sender_id)[:16] // 32 ฐานสิบหก
ciphertext = AES-GCM-เข้ารหัส (room_key, nonce, CBOR_payload, aad=room_id)

กรอบการคลายออก: { ประเภท: "m", ห้อง, msg: {id, ct, nonce, sender_pseudo, send_at} }

files.h2_f:
init POST /api/files/resumable/init {ชื่อไฟล์, ขนาด, chunk_size_hint}
            ← {upload_id, chunk_size}
อัน PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct ไบต์>
            ← 204
สรุป POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {file_id, url}
TTL เมื่อยังไม่เสร็จ: 24 ชม

files.h4_f:
ปฏิเสธ_รายการ = {
  "แอปพลิเคชัน/x-dosexec",
  "แอปพลิเคชัน/x-sharedlib",
  "แอปพลิเคชัน / x-mach-binary",
}
ถ้า magic.from_buffer(buf[:1024]) ใน deny_list: ส่งคืน 415

presence.h1_f:
ลูกค้า: ในการกดแป้นพิมพ์ครั้งแรก → ส่ง {type:"t", state:"start"}
         ไม่ส่งอีกต่อไปเป็นเวลา 3 วินาที เว้นแต่สถานะจะเปลี่ยนแปลง
         10 วินาทีหลังจากการกดแป้นพิมพ์ครั้งสุดท้าย → ส่ง {type:"t", state:"stop"}
ตัวรับสัญญาณ: หยุดอัตโนมัติ 10 วินาทีหลังจาก "เริ่มต้น" ครั้งล่าสุดหากไม่มี "หยุด" มาถึง

calls.h1_f:
POST /api/calls/{room_id}/start {วิดีโอ เสียง} → call_id
WS ออกอากาศ {type:"c", ชนิด:"invite", call_id}
WS ออกอากาศ {ประเภท:"c", ชนิด:"ข้อเสนอ", sdp}
WS ออกอากาศ {ประเภท:"c", ชนิด:"answer", sdp}
WS ออกอากาศ {type:"c", ชนิด:"candidate",ice} × N
POST /api/calls/{call_id}/end

federation.h2_f:
ซองจดหมาย = {
  source_node : hex32,
  target_user : int64,
  inner_ciphertext: ไบต์,
  inner_nonce : ไบต์
  send_at : unix_ms,
}
sig = Ed25519Sign(source_priv, CBOR(ซองจดหมาย))
POST /federation/deliver { ซองจดหมาย, ซิก }

gossip.h3_f:
โฆษณา = {pubkey จุดสิ้นสุด โฆษณา_at}
sig = Ed25519-Sign(pubkey_priv, CBOR(โฆษณา))
น้ำหนักบรรทุกซุบซิบ: [..., {ad, sig}, ...]

ผู้รับ: ตรวจสอบ sig กับ ad.pubkey → store iff ok
เพิ่มเติม: PoW ของ 2^18 ศูนย์นำหน้าบน {pubkey, endpoint}

stealth.h2_f:
ClientHello ไบต์ = chrome_120_template ด้วย {
  สุ่ม = สุ่มของเรา
  server_name = ชื่อโฮสต์ของเรา (หรือ ECH-ห่อ)
  session_id = รหัสเซสชันของเรา
}
JA4 = t13d_xxxx_xxxx_xxxx (ตรงกับ Chrome ที่เสถียรในปัจจุบัน)

stealth.h4_f:
กระทรวง: POST https://cloudflare-dns.com/dns-query {ชื่อ: x.vortexx.sol}
ECH: ClientHello.extensions += encrypted_sni(public_key_from_HTTPS_record)
DGA: โดเมน(t) = base32( SHA256(seed ∥ YYYY-MM-DD) )[:16] + ".example"

push.h4_f:
iOS NSE: didReceive(คำขอ) { ถอดรหัส(request.content.userInfo) }
Android FCM: onMessageReceived(remoteMessage) { ถอดรหัส (remoteMessage.data) }
เว็บ SW: self.addEventListener('push', e => decrypt(e.data))

controller.h2_f:
เครื่องมือ = sign_tool
input = แผนผังต้นทาง, คีย์/release.key
รายการ = {
  เวอร์ชัน: "0.1.0",
  build_at: unix_ms,
  ไฟล์: [{เส้นทาง, sha256, ขนาด}, ...]
}
sig = Ed25519-Sign (release_priv, CBOR (รายการ))
เอาท์พุท = INTEGRITY.sig.json = {รายการ, signed_by: pub_hex, sig: sig_hex}

bots.h1_f:
สร้าง: POST /api/bots {ชื่อผู้ใช้, display_name, รหัส}
          → {bot_id, โทเค็น, pubkey}
รัน: อยู่ระหว่างดำเนินการ (โครูทีนภายในโหนด)
      OR ภายนอก (แบบสำรวจความคิดเห็นแบบยาว /api/bots/{id}/updates, token-auth'd)
ข้อความ: {ข้อความ ลายเซ็น: Ed25519-Sign(bot_priv, canonical_msg)}

bots.h2_f:
บน / เริ่มต้น {
  ส่งเสียง "ยินดีต้อนรับ {ctx.first_name}"
}
บน / เพิ่ม <รายการ> {
  state.list = (state.list หรือ []) + [ctx.args.item]
  ปล่อย "เพิ่ม: {ctx.args.item}"
}

security.h4_f:
canary.txt (รายวัน):
  {วันที่ sig: Ed25519-Sign(release_priv, date)}
ลูกค้าตรวจสอบ → ขาดหรือไม่ถูกต้อง ⇒ สงสัยว่ามีการประนีประนอม

กรณีฉุกเฉิน:
  ผู้ดูแลระบบ POST /api/admin/revoid-all {เหตุผล}
  การออกอากาศโหนด {ประเภท: "n", เหตุการณ์: "ประนีประนอม", เหตุผล}
  ไคลเอนต์ล้างคีย์ บังคับให้บูตสแตรปใหม่

debugging.h2_f:
อัตราฮิสโตแกรม (ต่อเส้นทาง + วิธี):
  vortex_http_requests_total {เส้นทาง วิธีการ สถานะ}
  vortex_http_request_duration_seconds_bucket {เส้นทาง, วิธี, le}

เกจวัดเว็บซ็อคเก็ต:
  vortex_ws_connections{โหนด}
  vortex_ws_fanout_queue_detail{ห้อง,ผู้ใช้}

เคาน์เตอร์ที่กำหนดเอง:
  vortex_messages_sent_total{room_type}
  vortex_calls_started_total{ชนิด}

