fts5.h1_f:
CREATE VIRTUAL TABLE Messages_fts USING fts5(
  เนื้อหา -- คอลัมน์โทเค็น
  room_id UNINDEXED,
  tokenize = 'unicode61 Remove_diacritics 2'
);
ข้อความค้นหา: SELECT rowid FROM Messages_fts WHERE content MATCH 'foo'

